// Classify one incoming email and build the signed payload the site expects.
// type: bounce | auto_reply | unsubscribe | reply. Our own sent copies are skipped.
const OUR_ADDRESS = ($env.CRMA_OUTREACH_ADDRESS || '').toLowerCase();
const m = $json;
const lower = v => String(v || '').toLowerCase();
const firstAddress = v => {
  if (!v) return null;
  if (v.value && v.value[0] && v.value[0].address) return lower(v.value[0].address);
  const x = /([^<>\s"]+@[^<>\s"]+\.[^<>\s"]+)/.exec(String(v.text || v));
  return x ? lower(x[1]) : null;
};
const header = name => {
  const h = m.headers || {};
  const v = h[name] ?? h[name.toLowerCase()];
  return Array.isArray(v) ? v.join(' ') : (v && v.text ? v.text : v) || '';
};
const from = firstAddress(m.from);
if (OUR_ADDRESS && from === OUR_ADDRESS) return null;
const text = String(m.text || '').slice(0, 20000);
const subject = String(m.subject || '');
const refs = [].concat(m.references || []).join(' ');
let type = 'reply';
let recipient = null;
let references = refs;
const isDsn = /mailer-daemon|postmaster/.test(lower(from)) || /multipart\/report/i.test(header('content-type')) || /undeliver|delivery status notification|delivery has failed|returned mail|failure notice|mail delivery failed/i.test(subject);
if (isDsn) {
  type = 'bounce';
  const r = /Final-Recipient:\s*rfc822;\s*<?([^\s>]+)>?/i.exec(text) || /Original-Recipient:\s*rfc822;\s*<?([^\s>]+)>?/i.exec(text) || /<([^<>\s]+@[^<>\s]+)>:/.exec(text);
  recipient = r ? lower(r[1]) : null;
  // The bounced message's own Message-ID, quoted in the DSN body, matches our sent email.
  const orig = /^Message-ID:\s*(<[^>\s]+>)/im.exec(text);
  if (orig) references = (references + ' ' + orig[1]).trim();
} else if ((lower(header('auto-submitted')) && lower(header('auto-submitted')) !== 'no') || header('x-autoreply') || header('x-autorespond') || /auto_reply|auto-reply/i.test(header('precedence')) || /^(auto(matic)?[ -]?reply|out of (the )?office|ooo\b|abwesenheit|absence)/i.test(subject)) {
  type = 'auto_reply';
} else if (/^\s*(unsubscribe|stop|remove me|please remove|no thanks|not interested)\b/i.test(text)) {
  type = 'unsubscribe';
}
const payload = JSON.stringify({
  type,
  from,
  to: firstAddress(m.to),
  subject: subject.slice(0, 300),
  inReplyTo: m.inReplyTo || null,
  messageId: m.messageId || null,
  references,
  recipient,
  receivedAt: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),
  snippet: text.split(/\n\s*(>|On .+ wrote:)/)[0].replace(/\s+/g, ' ').trim().slice(0, 300)
});
const ts = Math.floor(Date.now() / 1000);
return { json: { ts, payload, signInput: ts + '.' + payload } };
